import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.D_bNC8Ic.js";const m=JSON.parse('{"title":"Maps, meta, globals","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/extmap-meta.md","filePath":"developers/commands/extmap-meta.md"}'),s={name:"developers/commands/extmap-meta.md"};function c(n,e,r,p,l,i){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="maps-meta-globals" tabindex="-1">Maps, meta, globals <a class="header-anchor" href="#maps-meta-globals" aria-label="Permalink to &quot;Maps, meta, globals&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; extmap add ch=1 cc=20 target=lfo lfo=2 domain=s32 lfo-param=rate</span></span>
<span class="line"><span>s32&gt; extmap list</span></span>
<span class="line"><span>s32&gt; extmap set 1 ch=2 cc=21 target=lfo lfo=2 domain=s32 lfo-param=rate</span></span>
<span class="line"><span>s32&gt; extmap remove 1</span></span>
<span class="line"><span>s32&gt; meta get</span></span>
<span class="line"><span>s32&gt; meta set bpm=137.5 description=Live-set-A</span></span>
<span class="line"><span>s32&gt; globals get</span></span>
<span class="line"><span>s32&gt; globals set bpm=128 clockMode=internal</span></span></code></pre></div><h2 id="external-midi-map" tabindex="-1">External MIDI map <a class="header-anchor" href="#external-midi-map" aria-label="Permalink to &quot;External MIDI map&quot;">​</a></h2><p>Incoming CC on a channel, mapped to a device parameter, an LFO parameter, a rack BYPASS or a snapshot control.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>extmap list</code></td><td>Every row, with its target</td></tr><tr><td><code>extmap add ch=CH cc=CC target=…</code></td><td>Adds a row for that channel (1–16) and CC. <code>target=</code> is required</td></tr><tr><td><code>extmap set INDEX ch=CH cc=CC target=…</code></td><td>Rewrites that row in place. <code>target=</code> is required</td></tr><tr><td><code>extmap remove INDEX</code></td><td>Deletes that row</td></tr></tbody></table><p>Target words for <code>extmap add</code> and <code>extmap set</code>:</p><table tabindex="0"><thead><tr><th>Target</th><th>Fields</th><th>Example</th></tr></thead><tbody><tr><td><code>target=device</code></td><td><code>rack=</code>, <code>device=</code>, <code>param=</code>, optional <code>sub=</code> for a Step Seq step</td><td><code>extmap add ch=1 cc=20 target=device rack=100 device=1 param=179 sub=2</code></td></tr><tr><td><code>target=lfo</code></td><td><code>lfo=</code>, <code>domain=s32</code>, <code>lfo-param=</code> (also <code>lfoParam=</code>)</td><td><code>extmap add ch=1 cc=21 target=lfo lfo=2 domain=s32 lfo-param=rate</code></td></tr><tr><td><code>target=rack-bypass</code> (also <code>rack</code>)</td><td><code>rack=</code></td><td><code>extmap add ch=1 cc=22 target=rack-bypass rack=100</code></td></tr><tr><td><code>target=snapshot-slot</code></td><td><code>part=</code>, optional <code>pad=</code> (<code>1</code>–<code>32</code>)</td><td><code>extmap add ch=1 cc=23 target=snapshot-slot part=knobs pad=5</code></td></tr><tr><td><code>target=morph-amount</code></td><td><code>part=</code></td><td><code>extmap add ch=1 cc=24 target=morph-amount part=knobs</code></td></tr></tbody></table><p><code>extmap list</code> prints one line per row, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  [1] src=0 ch=1 num=20 target=device rack=100 dev=1000 param=0 sub=none</span></span>
<span class="line"><span>  [2] src=0 ch=1 num=21 target=lfo domain=s32 lfo=2 lfo-param=rate</span></span>
<span class="line"><span>  [3] src=0 ch=1 num=22 target=rack-bypass rack=100</span></span></code></pre></div><p>A device, rack BYPASS or LFO target must be in the project: a rack, device or parameter that is not there exits <code>4</code> (<code>NotFound</code>) and changes nothing. Use the ids from <code>rack list</code> / <code>device list</code>, not positions, and a parameter that device has in <code>schema</code>.</p><p>A parameter has one mapping: one knob macro or one external row. Adding or retargeting a row on a mapped parameter clears its knob mapping, the same as picking <strong>EXTERNAL MAPPING</strong> on the S32. Only a change of target clears; editing the channel or CC number of the same target keeps the knob mapping. A read of the row shows the row that now holds the mapping.</p><p><code>part=</code> makes the CC pick a snapshot or drive a morph. On a snapshot slot, <code>pad=</code> maps that one pad instead of the whole bank; without it the note or Program Change numbers the whole bank from the learned number. See <a href="./snapshots#mapping">Snapshots</a>.</p><h2 id="project-meta" tabindex="-1">Project meta <a class="header-anchor" href="#project-meta" aria-label="Permalink to &quot;Project meta&quot;">​</a></h2><p><code>meta get</code> prints the project&#39;s BPM, clock mode, channel, encoder button action, tags and description. <code>meta set bpm=NUMBER description=TEXT</code> writes the BPM and description and keeps the tags.</p><h2 id="globals" tabindex="-1">Globals <a class="header-anchor" href="#globals" aria-label="Permalink to &quot;Globals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Where it lives</th></tr></thead><tbody><tr><td><code>clockMode</code></td><td><code>internal</code>, <code>external</code>, <code>auto</code></td><td>Project</td></tr><tr><td><code>bpm</code></td><td>Internal clock BPM</td><td>Project</td></tr><tr><td><code>globalChannel</code></td><td><code>1</code>–<code>16</code></td><td>Project</td></tr><tr><td><code>encoderBtn</code></td><td><code>clock</code>, <code>racks</code>, <code>lfos</code></td><td>Project</td></tr><tr><td><code>transport</code></td><td><code>stopped</code>, <code>running</code></td><td>Live only</td></tr></tbody></table><p>Project values change the project you are playing. <strong>SAVE PROJECT</strong> (or <code>project save</code>) keeps them.</p><h2 id="output-after-a-set" tabindex="-1">Output after a set <a class="header-anchor" href="#output-after-a-set" aria-label="Permalink to &quot;Output after a set&quot;">​</a></h2><p><code>extmap add</code> and <code>extmap set</code> print the row they wrote (<code>extmap list</code> format, no <code>external mappings: N</code> header), <code>meta set</code> and <code>globals set</code> print the project settings (<a href="./session#a-set-prints-the-state-it-left">A set prints the state it left</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback extmap add ch=1 cc=20 target=lfo lfo=2 domain=s32 lfo-param=rate</span></span>
<span class="line"><span>added external mapping row 1 (1 total)</span></span>
<span class="line"><span>  [1] src=0 ch=1 num=20 target=lfo domain=s32 lfo=2 lfo-param=rate</span></span>
<span class="line"><span>$ s32 --loopback --yes globals set bpm=130</span></span>
<span class="line"><span>globals updated</span></span>
<span class="line"><span>globalChannel=1 clockMode=internal bpm=130.00 transport=stopped encoderBtn=clock octaveEnc=0</span></span></code></pre></div><p><code>extmap set</code> already printed the row it sent, so the row shows twice: what the CLI sent, then what the S32 stored (they differ only when the S32 changes the row).</p><p>With <code>--json</code>, <code>extmap list</code> names the fields as <code>extmap add</code> takes them: <code>num=</code> is <code>cc</code>, <code>dev=</code> is <code>device</code>, <code>lfo-param</code> stays <code>lfo-param</code>, a field that does not apply to the row&#39;s target is <code>null</code> (<code>rack</code> is <code>null</code> while the rack is unset). <code>globals set --json</code> needs <code>--yes</code>: under <code>--json</code> it does not prompt, so without <code>--yes</code> it exits <code>5</code> with the <code>declined</code> error.</p>`,22)])])}const g=t(s,[["render",c]]);export{m as __pageData,g as default};
